def _make_centers(n):
    # Hexagonal-style layout: 5 rows with 5,6,5,6,4 = 26 circles.
    # Stagger rows so columns nest. Tighter margins let circles grow.
    rows = [5, 6, 5, 6, 4]
    n_rows = len(rows)
    y_margin = 0.10
    ys = np.linspace(y_margin, 1 - y_margin, n_rows)
    centers = []
    for cnt, y in zip(rows, ys):
        if cnt > 1:
            xs = np.linspace(0.10, 0.90, cnt)
        else:
            xs = np.array([0.5])
        for x in xs:
            centers.append([x, y])
    return np.array(centers)


