    for i in range(n):
        for j in range(i + 1, n):
            d = np.sqrt(np.sum((centers[i] - centers[j]) ** 2))
            D[i, j] = D[j, i] = d
    wall = np.array([min(x, y, 1 - x, 1 - y) for (x, y) in centers])
    radii = np.minimum(wall * 0.5, 0.1)
    for it in range(iters):
        improved = False
